function maxScoreIndices(nums) {
  let onesRight = 0;
  for (const bit of nums) {
    onesRight += bit;
  }
  let zerosLeft = 0;
  let best = onesRight;
  let result = [0];

  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === 0) {
      zerosLeft++;
    } else {
      onesRight--;
    }
    const score = zerosLeft + onesRight;
    if (score > best) {
      best = score;
      result = [i + 1];
    } else if (score === best) {
      result.push(i + 1);
    }
  }
  return result;
}

