function maxScoreIndices(nums) {
  const scores = [];
  for (let i = 0; i <= nums.length; i++) {
    const zeros = nums.slice(0, i).filter(v => v === 0).length;
    const ones = nums.slice(i).filter(v => v === 1).length;
    scores.push(zeros + ones);
  }
  const top = Math.max(...scores);
  const answer = [];
  scores.forEach((s, i) => { if (s === top) answer.push(i); });
  return answer;
}

