function generate(rand, size) {
  const length = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const chance = [0.5, 0.1, 0.9, 0.5][Math.floor(rand() * 4)];
  if (size === 'large' && rand() < 0.4) {
    // Alternating bits give many tied cuts.
    return [Array.from({ length }, (_, i) => (i % 2 === 0 ? 0 : 1))];
  }
  return [Array.from({ length }, () => (rand() < chance ? 1 : 0))];
}
